# Generated by build.py from recipe.yml for recipe ldap-search-with-a-filter-and-scope. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site/.surl/ldap
cat > site/.surl/ldap/directory.ldif <<'EOF'
dn: dc=example,dc=com
objectClass: domain
dc: example

dn: ou=people,dc=example,dc=com
objectClass: organizationalUnit
ou: people

dn: cn=alice,ou=people,dc=example,dc=com
objectClass: person
cn: alice
sn: Liddell
mail: alice@example.com

dn: cn=bob,ou=people,dc=example,dc=com
objectClass: person
cn: bob
sn: Builder
mail: bob@example.com

dn: ou=groups,dc=example,dc=com
objectClass: organizationalUnit
ou: groups

dn: cn=staff,ou=groups,dc=example,dc=com
objectClass: groupOfNames
cn: staff
member: cn=alice,ou=people,dc=example,dc=com
EOF
surl --directory site --allow-anonymous ldap://127.0.0.1:8080/ &
sleep 1
curl -u : "ldap://127.0.0.1:8080/ou=people,dc=example,dc=com?mail?one?(sn=B*)"
kill $(jobs -p)
